WITH unpacked AS (SELECT id, created_at, SIZE(FILTER(items, x -> x.qty >= 3)) AS bulk_lines, attributes['device'] AS device, TRANSFORM(items, x -> x.product_id) AS product_ids, COALESCE(ship_to.zip, 'UNKNOWN') AS zip_or_unknown, SIZE(items) AS num_items FROM carts) SELECT *, AVG(bulk_lines) OVER (ORDER BY num_items ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_bulk_lines, SUM(bulk_lines) OVER (ORDER BY num_items ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_bulk_lines, MIN(bulk_lines) OVER (ORDER BY num_items ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_bulk_lines FROM unpacked;
